import csv

def summarize_csv(path):
    result = {}
    with open(path, newline='', encoding='utf-8') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            tenant = row['tenant']
            cents = int(row['cents'])
            if tenant in result:
                result[tenant] += cents
            else:
                result[tenant] = cents
    return result
