def sort_integer_file(source, destination):
    with open(source, 'r', encoding='utf-8') as src_file:
        integers = [int(line.strip()) for line in src_file if line.strip()]

    integers.sort()

    with open(destination, 'w', encoding='utf-8') as dest_file:
        for number in integers:
            dest_file.write(f"{number}\n")

    return len(integers)
